#include <iostream>
#include <set>
#include <map>
#include <string>

int main() {
    // 1. std::set: Unique sorted keys
    std::set<int> uniqueNumbers{50, 10, 40, 10, 20};
    std::cout << "Set size: " << uniqueNumbers.size() << "\nSet elements: ";
    for (int num : uniqueNumbers) {
        std::cout << num << " ";
    }
    std::cout << "\n";

    // 2. std::multiset: Sorted keys with duplicates
    std::multiset<int> multiNumbers{50, 10, 40, 10, 20, 10};
    std::cout << "Multiset count(10): " << multiNumbers.count(10) << "\n";
    auto [low, up] = multiNumbers.equal_range(10); // C++17 structured binding
    std::cout << "Elements equal to 10: ";
    for (auto it = low; it != up; ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";

    // 3. std::multimap: One-to-many relationship
    std::multimap<std::string, int> scores{
        {"Alice", 95},
        {"Bob", 88},
        {"Alice", 99}
    };
    std::cout << "Scores for Alice:\n";
    auto range = scores.equal_range("Alice");
    for (auto it = range.first; it != range.second; ++it) {
        std::cout << "  " << it->first << ": " << it->second << "\n";
    }

    return 0;
}

#include <iostream>
#include <stack>
#include <queue>
#include <bitset>

int main() {
    // Container adapter: stack (LIFO)
    std::stack<int> intStack;
    intStack.push(10);
    intStack.push(20);
    intStack.push(30);
    std::cout << "Stack top: " << intStack.top() << "\n";
    intStack.pop();
    std::cout << "Stack top after pop: " << intStack.top() << "\n";

    // Container adapter: priority_queue (Max-Heap)
    std::priority_queue<int> pq;
    pq.push(15);
    pq.push(50);
    pq.push(25);
    std::cout << "Priority queue top: " << pq.top() << "\n";

    // Class bitset
    constexpr std::size_t NUM_FLAGS = 8;
    std::bitset<NUM_FLAGS> flags; // 00000000
    flags.set(1);
    flags.set(3);
    flags.set(7);
    std::cout << "Bitset flags: " << flags << "\n";
    std::cout << "Set bits count: " << flags.count() << "\n";
    flags.reset(3); // Turn off bit 3
    std::cout << "Bit 3 after reset: " << flags.test(3) << "\n";
    std::cout << "Flags shifted left by 1: " << (flags << 1) << "\n";

    return 0;
}
